<?php
$search=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??''); $currency=(string)($_GET['currency']??'');
$from=trim((string)($_GET['from']??'')); $to=trim((string)($_GET['to']??''));
$where=' WHERE 1=1'; $params=[];
if($buFilter!==null){ 
    $where.=' AND (p.business_unit_id=? OR (p.business_unit_id IS NULL AND ? = 1))'; 
    $params[]=$buFilter; 
    $params[]=$buFilter; 
}
if($search!==''){ $where.=" AND CONCAT_WS(' ',p.id,c.name,c.company,c.email,p.description,p.amount,REPLACE(p.amount,'.',','),p.base_amount,p.discount_amount,p.surcharge_amount,p.manual_adjustment_amount,p.renewal_months,p.renewal_days,p.renewal_end_date,DATE_FORMAT(p.renewal_end_date,'%d/%m/%Y'),p.currency,p.exchange_rate,p.exchange_rate_source,p.amount_brl,REPLACE(p.amount_brl,'.',','),p.fee_amount,p.fee_brl,p.net_brl,REPLACE(p.net_brl,'.',','),p.status,CASE p.status WHEN 'pending' THEN 'Pendente' WHEN 'paid' THEN 'Pago' WHEN 'failed' THEN 'Falhou' WHEN 'refunded' THEN 'Estornado' END,p.due_date,DATE_FORMAT(p.due_date,'%d/%m/%Y'),p.payment_date,DATE_FORMAT(p.payment_date,'%d/%m/%Y'),p.settlement_date,DATE_FORMAT(p.settlement_date,'%d/%m/%Y'),p.payment_method,p.external_reference,p.notes) LIKE ?"; $params[]='%'.$search.'%'; }
if(in_array($status,['pending','paid','failed','refunded'],true)){ $where.=' AND p.status=?';$params[]=$status; }
if(in_array($currency,['BRL','USD'],true)){ $where.=' AND p.currency=?';$params[]=$currency; }
$dateExpr="COALESCE(CASE WHEN p.currency='USD' THEN COALESCE(p.settlement_date,p.payment_date) ELSE p.payment_date END,p.due_date,DATE(p.created_at))";
if($from!==''){ $where.=" AND {$dateExpr} >= ?"; $params[]=$from; }
if($to!==''){ $where.=" AND {$dateExpr} <= ?"; $params[]=$to; }
$pagination=pagination($db,'SELECT COUNT(*) FROM payments p JOIN clients c ON c.id=p.client_id'.$where,'SELECT p.*,c.name client FROM payments p JOIN clients c ON c.id=p.client_id'.$where." ORDER BY {$dateExpr} DESC,p.id DESC",$params);
$edit=isset($_GET['edit'])?$db->fetch('SELECT * FROM payments WHERE id=?',[(int)$_GET['edit']]):null; $showForm=isset($_GET['new'])||$edit;
$clientsQuery="SELECT id,name,preferred_currency FROM clients WHERE (status!='inactive' OR id=?)";
$clientsParams=[(int)($edit['client_id']??0)];
if ($buFilter !== null && !$edit) {
    $clientsQuery .= " AND (business_unit_id=? OR (business_unit_id IS NULL AND ? = 1))";
    $clientsParams[] = $buFilter;
    $clientsParams[] = $buFilter;
}
$clientsQuery .= " ORDER BY name";
$clients=$showForm?$db->fetchAll($clientsQuery, $clientsParams):[];

$subscriptionsQuery="SELECT s.id,s.client_id,s.currency,s.unit_price,s.quantity,s.discount,c.name client,p.name product FROM subscriptions s JOIN clients c ON c.id=s.client_id JOIN products p ON p.id=s.product_id WHERE (s.status!='canceled' OR s.id=?)";
$subscriptionsParams=[(int)($edit['subscription_id']??0)];
if ($buFilter !== null && !$edit) {
    $subscriptionsQuery .= " AND (c.business_unit_id=? OR (c.business_unit_id IS NULL AND ? = 1))";
    $subscriptionsParams[] = $buFilter;
    $subscriptionsParams[] = $buFilter;
}
$subscriptionsQuery .= " ORDER BY c.name,p.name";
$subscriptions=$showForm?$db->fetchAll($subscriptionsQuery, $subscriptionsParams):[];
[$rangeFrom,$rangeTo]=period_dates();
$statFrom=$from!==''?$from:$rangeFrom;
$statTo=$to!==''?$to:$rangeTo;
$statLabel=($from!==''||$to!=='')?'no período':'no mês';
$totalsWhere = "COALESCE(CASE WHEN currency='USD' THEN COALESCE(settlement_date,payment_date) ELSE payment_date END,payment_date,due_date,DATE(created_at)) BETWEEN ? AND ?";
$totalsParams = [$statFrom,$statTo];
if ($buFilter !== null) {
    $totalsWhere .= " AND (business_unit_id = ? OR (business_unit_id IS NULL AND ? = 1))";
    $totalsParams[] = $buFilter;
    $totalsParams[] = $buFilter;
}
$paymentTotals=$db->fetch("SELECT COALESCE(SUM(CASE WHEN status='paid' THEN amount_brl ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN status='pending' THEN amount_brl ELSE 0 END),0) pending,COALESCE(SUM(CASE WHEN status='paid' THEN fee_brl ELSE 0 END),0) fees FROM payments WHERE " . $totalsWhere, $totalsParams);
$pageHasPending=count(array_filter($pagination['rows'],static fn(array $row):bool=>$row['status']==='pending'))>0;
?>
<section class="mini-stats money-stats" data-live-results><div><span class="dot green"></span><span><small>Recebido <?= $statLabel ?></small><b><?= money($paymentTotals['paid']) ?></b></span></div><div><span class="dot gold"></span><span><small>Pendente <?= $statLabel ?></small><b><?= money($paymentTotals['pending']) ?></b></span></div><div><span class="dot red"></span><span><small>Taxas <?= $statLabel ?></small><b><?= money($paymentTotals['fees']) ?></b></span></div></section>
<section class="toolbar list-toolbar"><form class="search-filters" method="get" data-live-filter><input type="hidden" name="page" value="payments"><label class="search-box">⌕<input name="q" autocomplete="off" placeholder="Buscar qualquer informação" value="<?= h($search) ?>"></label><select name="currency"><option value="">BRL + USD</option><option value="BRL" <?= $currency==='BRL'?'selected':'' ?>>BRL</option><option value="USD" <?= $currency==='USD'?'selected':'' ?>>USD</option></select><select name="status"><option value="">Todos os status</option><option value="paid" <?= $status==='paid'?'selected':'' ?>>Pagos</option><option value="pending" <?= $status==='pending'?'selected':'' ?>>Pendentes</option><option value="failed" <?= $status==='failed'?'selected':'' ?>>Falhos</option><option value="refunded" <?= $status==='refunded'?'selected':'' ?>>Estornados</option></select><label>De<input type="date" name="from" value="<?= h($from) ?>"></label><label>Até<input type="date" name="to" value="<?= h($to) ?>"></label><span class="live-filter-indicator" data-live-filter-indicator aria-live="polite">Busca automática</span></form><div><?php if($auth->canWrite()): ?><label class="bulk-date">Recebidos em<input form="bulk-payments" name="settlement_date" type="date" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></label><button form="bulk-payments" class="button receive-button" data-bulk-submit disabled>✓ Confirmar selecionados</button><?php endif; ?><a class="button ghost" href="?page=export&type=payments">⇩ Exportar</a><?php if($auth->canWrite()): ?><a class="button primary" href="?page=payments&new=1">＋ Novo pagamento</a><?php endif; ?></div></section>
<div data-live-results>
<form id="bulk-payments" method="post" data-confirm="Confirmar os pagamentos selecionados como recebidos na data informada?"><?= csrf_field() ?><input type="hidden" name="action" value="mark_payments_paid"><section class="card table-card"><div class="table-meta"><span><b><?= $pagination['total'] ?></b> pagamentos</span><?php if($pageHasPending): ?><small>Selecione os pendentes para confirmar em lote.</small><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th class="check-column"><?php if($pageHasPending): ?><input type="checkbox" data-check-all aria-label="Selecionar pendentes desta página"><?php endif; ?></th><th>Pagamento</th><th>Pagamento / Resgate</th><th>Valor original</th><th>Cotação usada</th><th>Líquido em BRL</th><th>Status</th><th></th></tr></thead><tbody>
<?php if(!$pagination['rows']): ?><tr><td colspan="8" class="empty-cell">Nenhum pagamento encontrado.</td></tr><?php endif; ?>
<?php foreach($pagination['rows'] as $item): ?><tr><td class="check-column"><?php if($item['status']==='pending'&&$auth->canWrite()): ?><input type="checkbox" name="payment_ids[]" value="<?= (int)$item['id'] ?>" data-payment-check aria-label="Selecionar pagamento de <?= h($item['client']) ?>"><?php endif; ?></td><td><div class="entity"><span class="avatar-sm"><?= h(mb_strtoupper(mb_substr($item['client'],0,1))) ?></span><span><b><?= h($item['client']) ?></b><small><?= h($item['description']?:$item['external_reference']?:'Pagamento') ?></small><?php if($item['renewal_months']!==null): ?><small class="payment-coverage"><?= renewal_period_label($item['renewal_months'],$item['renewal_days']) ?> · próxima <?= date_br($item['renewal_end_date']) ?></small><?php endif; ?></span></div></td><td><b><?= date_br($item['payment_date']?:$item['due_date']) ?></b><?php if($item['currency']==='USD'): ?><small class="block">Resgate: <?= date_br($item['settlement_date']) ?></small><?php endif; ?></td><td><b><?= money($item['amount'],$item['currency']) ?></b><?php if($item['base_amount']!==null): ?><small class="block">Base <?= money($item['base_amount'],$item['currency']) ?> · desconto <?= money($item['discount_amount'],$item['currency']) ?> · acréscimo <?= money($item['surcharge_amount'],$item['currency']) ?></small><?php endif; ?><?php if(abs((float)$item['manual_adjustment_amount'])>0.009): ?><small class="block">Ajuste manual: <?= money($item['manual_adjustment_amount'],$item['currency']) ?></small><?php endif; ?><?php if($item['fee_amount']>0): ?><small class="block">Taxa: <?= money($item['fee_amount'],$item['currency']) ?></small><?php endif; ?></td><td><?= $item['currency']==='USD'?'R$ '.number_format($item['exchange_rate'],4,',','.'):'—' ?><?php if($item['currency']==='USD'): ?><small class="block"><?= h($item['exchange_rate_source']?:'Estimativa') ?></small><?php endif; ?></td><td><b><?= money($item['net_brl']) ?></b></td><td><span class="badge <?= status_class($item['status']) ?>"><?= status_label($item['status']) ?></span></td><td><a class="row-action" href="?page=payments&edit=<?= (int)$item['id'] ?>">•••</a></td></tr><?php endforeach; ?>
</tbody></table></div><?= render_pagination($pagination) ?></section></form>
</div>
<?php if($showForm): ?><div class="modal open"><a class="modal-backdrop" href="?page=payments"></a><section class="modal-panel wide"><header><div><p class="eyebrow">RECEBIMENTOS</p><h2><?= $edit?'Editar pagamento':'Novo pagamento' ?></h2></div><a href="?page=payments" class="modal-close">×</a></header><form method="post" class="form-grid" data-money-form data-daily-rate="1" data-new-record="<?= $edit?'0':'1' ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save_payment"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="_return" value="<?= h($_SERVER['REQUEST_URI']) ?>"><input type="hidden" name="exchange_rate_source" data-rate-source value="<?= h($edit['exchange_rate_source']??'') ?>"><input type="hidden" name="business_unit_id" value="<?= (int)($edit ? ($edit['business_unit_id']??0) : ($buFilter ?: 1)) ?>">
<label>Cliente<select name="client_id" required data-payment-client><option value="">Selecione…</option><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>" data-currency="<?= h($client['preferred_currency']) ?>" <?= (int)($edit['client_id']??0)===(int)$client['id']?'selected':'' ?>><?= h($client['name']) ?></option><?php endforeach; ?></select></label><label>Assinatura (opcional)<select name="subscription_id" data-payment-sub><option value="">Pagamento avulso</option><?php foreach($subscriptions as $sub): $subValue=max(0,$sub['unit_price']*$sub['quantity']-$sub['discount']); ?><option value="<?= (int)$sub['id'] ?>" data-client="<?= (int)$sub['client_id'] ?>" data-currency="<?= h($sub['currency']) ?>" data-amount="<?= h($subValue) ?>" <?= (int)($edit['subscription_id']??0)===(int)$sub['id']?'selected':'' ?>><?= h($sub['client'].' · '.$sub['product']) ?></option><?php endforeach; ?></select></label><label class="span-2">Descrição<input name="description" value="<?= h($edit['description']??'') ?>" placeholder="Ex.: Mensalidade de julho"></label><label>Moeda<select name="currency" data-money-currency><option value="BRL" <?= ($edit['currency']??'BRL')==='BRL'?'selected':'' ?>>BRL — Real</option><option value="USD" <?= ($edit['currency']??'')==='USD'?'selected':'' ?>>USD — Dólar</option></select></label><label>Valor recebido<input name="amount" type="number" step="0.01" min="0.01" required data-money-amount value="<?= decimal_input($edit['amount']??0) ?>"></label><label>Taxa da plataforma (na mesma moeda)<input name="fee_amount" type="number" step="0.01" min="0" data-money-fee value="<?= decimal_input($edit['fee_amount']??0) ?>"></label><label>Cotação USD → BRL<input name="exchange_rate" type="number" step="0.000001" min="0" data-money-rate value="<?= h($edit['exchange_rate']??'') ?>" placeholder="Preenchida pela data do resgate"><small data-rate-help><?= $edit?'Cotação salva neste pagamento':'Aguardando a data do resgate' ?></small></label><label>Data do resgate em BRL<input name="settlement_date" type="date" data-rate-date value="<?= h($edit ? ($edit['settlement_date']??'') : date('Y-m-d')) ?>"><small>Dia em que o saldo em dólar foi convertido ou retirado.</small></label><div class="conversion-preview span-2"><span>Valor líquido convertido</span><strong data-money-preview>R$ 0,00</strong><small>A cotação diária do resgate ficará registrada e não mudará depois.</small></div><label>Status<select name="status"><option value="paid" <?= ($edit['status']??'paid')==='paid'?'selected':'' ?>>Pago</option><option value="pending" <?= ($edit['status']??'')==='pending'?'selected':'' ?>>Pendente</option><option value="failed" <?= ($edit['status']??'')==='failed'?'selected':'' ?>>Falhou</option><option value="refunded" <?= ($edit['status']??'')==='refunded'?'selected':'' ?>>Estornado</option></select></label><label>Forma de pagamento<input name="payment_method" value="<?= h($edit['payment_method']??'') ?>" placeholder="Stripe, PIX, cartão…"></label><label>Vencimento<input name="due_date" type="date" value="<?= h($edit['due_date']??date('Y-m-d')) ?>"></label><label>Data do pagamento<input name="payment_date" type="date" value="<?= h($edit['payment_date']??date('Y-m-d')) ?>"></label><label class="span-2">Referência externa<input name="external_reference" value="<?= h($edit['external_reference']??'') ?>" placeholder="ID do Stripe, banco ou nota fiscal"></label><label class="span-2">Observações<textarea name="notes" rows="3"><?= h($edit['notes']??'') ?></textarea></label><footer class="span-2"><a class="button ghost" href="?page=payments">Cancelar</a><button class="button primary">Salvar pagamento</button></footer></form><?php if($edit&&$auth->canWrite()): ?><form method="post" class="danger-zone" data-confirm="Excluir este pagamento? O dashboard será recalculado."><?= csrf_field() ?><input type="hidden" name="action" value="delete_payment"><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><button>Excluir pagamento</button></form><?php endif; ?></section></div><?php endif; ?>
